// NewSecret returns a new signing secret for an endpoint.
func NewSecret() string { return store.NewToken("whsec_") }

// SecretOverlap is how long a rotated-out secret keeps signing deliveries.
const SecretOverlap = 24 * time.Hour

// DefaultTolerance is how far a delivery's timestamp may be from the receiver's clock when Verify is given no tolerance.
const DefaultTolerance = 5 * time.Minute

// Errors returned by Verify, checked in this order.
var (
	ErrMalformedHeader    = errors.New("malformed signature header")
	ErrNoTimestamp        = errors.New("signature header has no timestamp")
	ErrTimestampTolerance = errors.New("signature timestamp is outside the tolerance")
	ErrNoSignature        = errors.New("signature header has no v1 signature")
	ErrSignatureMismatch  = errors.New("no signature matches")
)

// Sign returns the signature of a delivery's body: the hex HMAC-SHA256 of the body, keyed with the endpoint's secret.
func Sign(secret string, body []byte) string {
	m := hmac.New(sha256.New, []byte(secret))
	m.Write(body)
	return hex.EncodeToString(m.Sum(nil))
}

// signPayload returns the hex HMAC-SHA256 of "<ts>.<payload>", keyed with secret.
func signPayload(secret, ts string, payload []byte) string {
	return Sign(secret, append([]byte(ts+"."), payload...))
}

// SignatureHeader returns the Tally-Signature header of a delivery sent at t: "t=<unix seconds>" followed by one
// "v1=<signature>" for each secret, current first. The signature covers "<t>.<body>".
func SignatureHeader(secrets []string, t time.Time, body []byte) string {
	ts := strconv.FormatInt(t.Unix(), 10)
	var b strings.Builder
	b.WriteString("t=" + ts)
	for _, secret := range secrets {
		b.WriteString(",v1=" + signPayload(secret, ts, body))
	}
	return b.String()
}

// Verify checks a delivery's payload against its Tally-Signature header. It returns nil when the header's timestamp is
// within tolerance of now (in either direction; 0 means DefaultTolerance) and one of its v1 signatures matches the payload
// signed with one of secrets. Use the endpoint's current secret and, during a rotation, its previous one.
func Verify(payload []byte, header string, secrets []string, tolerance time.Duration, now time.Time) error {
	if strings.TrimSpace(header) == "" {
		return fmt.Errorf("%w: the header is empty", ErrMalformedHeader)
	}
	var ts string
	var t int64
	hasT := false
	var sigs []string
	for _, pair := range strings.Split(header, ",") {
		pair = strings.TrimSpace(pair)
		k, v, ok := strings.Cut(pair, "=")
		if !ok {
			return fmt.Errorf("%w: %q is not key=value", ErrMalformedHeader, pair)
		}
		k, v = strings.TrimSpace(k), strings.TrimSpace(v)
		switch k {
		case "t":
			n, err := strconv.ParseInt(v, 10, 64)
			if err != nil {
				return fmt.Errorf("%w: t is not an integer", ErrMalformedHeader)
			}
			if !hasT {
				ts, t, hasT = v, n, true
			}
		case "v1":
			sigs = append(sigs, v)
		}
	}
	if !hasT {
		return ErrNoTimestamp
	}
	if tolerance == 0 {
		tolerance = DefaultTolerance
	}
	if d := now.Sub(time.Unix(t, 0)); d > tolerance || d < -tolerance {
		return fmt.Errorf("%w: the timestamp is %v from now", ErrTimestampTolerance, d)
	}
	if len(sigs) == 0 {
		return ErrNoSignature
	}
	matched := false
	for _, sig := range sigs {
		for _, secret := range secrets {
			if hmac.Equal([]byte(sig), []byte(signPayload(secret, ts, payload))) {
				matched = true
			}
		}
	}
	if !matched {
		return ErrSignatureMismatch
	}
	return nil
