// rotateEndpointSecret gives an endpoint a new signing secret. The old one keeps signing its deliveries for 24 hours.
func (s *Server) rotateEndpointSecret(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	now := s.clock.Now()
	secret := webhooks.NewSecret()
	ep, err := s.store.UpdateWebhookEndpoint(p.OrgID, r.PathValue("id"), func(ep *store.WebhookEndpoint) error {
		ep.PreviousSecret = ep.Secret
		ep.Secret = secret
		ep.SecretRotatedAt = &now
		return nil
	})
	if err != nil {
		s.storeError(w, err)
		return
	}
	writeJSON(w, http.StatusOK, ep)
}

