func TestSignatureHeader(t *testing.T) {
	at := time.Unix(1700000000, 0)
	body := []byte(`{"id":"evt_1"}`)
	signed := func(secret string) string { return webhooks.Sign(secret, []byte("1700000000."+string(body))) }
	got := webhooks.SignatureHeader([]string{"whsec_new", "whsec_old"}, at, body)
	if want := "t=1700000000,v1=" + signed("whsec_new") + ",v1=" + signed("whsec_old"); got != want {
		t.Fatalf("SignatureHeader = %q, want %q", got, want)
	}
	if got := webhooks.SignatureHeader([]string{"whsec_new"}, at, body); got != "t=1700000000,v1="+signed("whsec_new") {
		t.Fatalf("one secret: SignatureHeader = %q", got)
	}
}

func TestVerify(t *testing.T) {
	now := time.Unix(1700000000, 0)
	body := []byte(`{"id":"evt_1"}`)
	secrets := []string{"whsec_new"}
	signed := webhooks.SignatureHeader(secrets, now, body)
	sig := strings.TrimPrefix(signed[strings.Index(signed, "v1="):], "v1=")
	stale := webhooks.SignatureHeader(secrets, now.Add(-time.Hour), body)
	for _, tc := range []struct {
		name      string
		header    string
		payload   []byte
		secrets   []string
		tolerance time.Duration
		now       time.Time
		want      error
	}{
		{"valid", signed, body, secrets, 0, now, nil},
		{"previous secret matches the second entry", webhooks.SignatureHeader([]string{"whsec_new", "whsec_old"}, now, body), body, []string{"whsec_old"}, 0, now, nil},
		{"any order, spaces, unknown keys and a wrong v1 first", "v0=abc , v1=00 ,v1=" + sig + ", t=1700000000", body, secrets, 0, now, nil},
		{"five minutes ahead", signed, body, secrets, 0, now.Add(5 * time.Minute), nil},
		{"five minutes behind", signed, body, secrets, 0, now.Add(-5 * time.Minute), nil},
		{"just over five minutes ahead", signed, body, secrets, 0, now.Add(5*time.Minute + time.Second), webhooks.ErrTimestampTolerance},
		{"just over five minutes behind", signed, body, secrets, 0, now.Add(-5*time.Minute - time.Second), webhooks.ErrTimestampTolerance},
		{"custom tolerance", signed, body, secrets, time.Minute, now.Add(2 * time.Minute), webhooks.ErrTimestampTolerance},
		{"custom tolerance accepts", signed, body, secrets, time.Minute, now.Add(time.Minute), nil},
		{"wrong secret", signed, body, []string{"whsec_other"}, 0, now, webhooks.ErrSignatureMismatch},
		{"tampered body", signed, []byte(`{"id":"evt_2"}`), secrets, 0, now, webhooks.ErrSignatureMismatch},
		{"no secrets", signed, body, nil, 0, now, webhooks.ErrSignatureMismatch},
		{"empty header", "", body, secrets, 0, now, webhooks.ErrMalformedHeader},
		{"blank header", "  ", body, secrets, 0, now, webhooks.ErrMalformedHeader},
		{"pair without =", "t=1700000000,v1", body, secrets, 0, now, webhooks.ErrMalformedHeader},
		{"empty pair", "t=1700000000,,v1=" + sig, body, secrets, 0, now, webhooks.ErrMalformedHeader},
		{"t is not an integer", "t=yesterday,v1=" + sig, body, secrets, 0, now, webhooks.ErrMalformedHeader},
		{"t is empty", "t=,v1=" + sig, body, secrets, 0, now, webhooks.ErrMalformedHeader},
		{"malformed pair before a missing t", "v1=" + sig + ",oops", body, secrets, 0, now, webhooks.ErrMalformedHeader},
		{"no t", "v1=" + sig, body, secrets, 0, now, webhooks.ErrNoTimestamp},
		{"no v1", "t=1700000000", body, secrets, 0, now, webhooks.ErrNoSignature},
		{"only v0", "t=1700000000,v0=" + sig, body, secrets, 0, now, webhooks.ErrNoSignature},
		{"stale timestamp is checked before the missing signature", "t=1600000000", body, secrets, 0, now, webhooks.ErrTimestampTolerance},
		{"stale timestamp is checked before a mismatch", stale, body, []string{"whsec_other"}, 0, now, webhooks.ErrTimestampTolerance},
	} {
		err := webhooks.Verify(tc.payload, tc.header, tc.secrets, tc.tolerance, tc.now)
		if tc.want == nil && err != nil || tc.want != nil && !errors.Is(err, tc.want) {
			t.Errorf("%s: Verify = %v, want %v", tc.name, err, tc.want)
		}
	}
}

