func TestDeliveriesSignWithRotatedSecret(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	now := e.Clock.Now()
	rotated := now.Add(-time.Hour)
	ep, _ := e.Store.CreateWebhookEndpoint(store.WebhookEndpoint{OrgID: e.Acme.ID, URL: "https://hooks.acme.example/all", Events: []string{"*"}, Secret: "whsec_new", PreviousSecret: "whsec_old", SecretRotatedAt: &rotated, Enabled: true}, now)
	if err := e.Webhooks.Publish(ctx, e.Acme.ID, "customer.created", map[string]string{"id": "cus_1"}); err != nil {
		t.Fatal(err)
	}
	if n, err := e.Webhooks.RunDue(ctx); err != nil || n != 1 {
		t.Fatalf("RunDue = %d, %v", n, err)
	}
	h := e.HTTP.Requests()[0].Header.Get("Tally-Signature")
	if reqs := e.HTTP.Requests(); strings.Count(h, "v1=") != 2 || !strings.HasPrefix(h, "t="+strconv.FormatInt(now.Unix(), 10)+",") || webhooks.Verify(reqs[0].Body, h, []string{"whsec_new", "whsec_old"}, 0, now) != nil {
		t.Fatalf("within 24 hours of a rotation: %q", h)
	}

	e.Clock.Advance(webhooks.SecretOverlap)
	if err := e.Webhooks.Publish(ctx, e.Acme.ID, "customer.created", map[string]string{"id": "cus_2"}); err != nil {
		t.Fatal(err)
	}
	if n, err := e.Webhooks.RunDue(ctx); err != nil || n != 1 {
		t.Fatalf("RunDue = %d, %v", n, err)
	}
	reqs := e.HTTP.Requests()
	h = reqs[len(reqs)-1].Header.Get("Tally-Signature")
	if strings.Count(h, "v1=") != 1 || webhooks.Verify(reqs[len(reqs)-1].Body, h, []string{"whsec_new"}, 0, e.Clock.Now()) != nil {
		t.Fatalf("after 24 hours: %q", h)
	}
	if got, _ := e.Store.WebhookEndpoint(e.Acme.ID, ep.ID); got.PreviousSecret != "whsec_old" {
		t.Fatalf("endpoint = %+v", got)
	}
}
